[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<!-- Header for Frappe Print Format -->
<style>
  @import url('https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Cairo:wght@500;700&display=swap');

  .header-wrap {
    width: 100%;
    text-align: center;
    direction: rtl;
    margin-bottom: 20px;
    font-family: "Cairo", "Amiri", "Tahoma", "Arial", sans-serif;
  }

  .header-top {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    margin-bottom: 12px;
  }

  .logo-img {
    max-width: 135px;
    max-height: 95px;
    display: block;
  }

  /* BARCODE - left aligned */
  .barcode-img {
    position: absolute;
    left: 5%;
    max-width: 250;
    max-height: 105;
  }

  /* ORG INFO - right aligned */
  .org-lines {
    position: absolute;
    right: 5%;
    text-align: right;
    line-height: 1.7;
    font-size: 14px;
    font-weight: 700;
  }

  .center-title {
    font-size: 28px;
    font-weight: 800;
    letter-spacing: 1px;
    margin-top: 5px;
    font-family: "Amiri", "Cairo", serif;
  }

  /* Separator line */
  .header-line {
    width: 95%;
    height: 1.5px;
    background-color: #999;
    margin: 10px auto 0 auto;
    border-radius: 2px;
  }

  @media print {
    .logo-img { max-width: 130px; max-height: 90px; }
    .barcode-img { max-width: 190px; max-height: 80px; left: 4%; }
    .org-lines { right: 4%; font-size: 13px; }
    .center-title { font-size: 26px; }
    .header-line { background-color: #bbb; height: 1px; }
  }
</style>

<div class="header-wrap">
  <div class="header-top">
    <!-- BARCODE on the left -->
    {% if doc.barcode_image %}
      <img class="barcode-img" src="{{ doc.qr_code_image }}" alt="Barcode" onerror="this.style.display='none'"/>
    {% endif %}

    <!-- CENTER LOGO -->
    <img class="logo-img" src="http://128.38.20.170/files/erpnext-hero-compressedbcc972.jpg" alt="Logo" onerror="this.style.display='none'"/>

    <!-- ORG INFO on the right -->
    <div class="org-lines">
      <div>وزارة الدفاع</div>
      <div>إدارة المهندسين العسكريين</div>
      <div>الكتيبة ٨ إصلاح ونجدة</div>
    </div>
  </div>

<div class="center-title">
  {% if doc.repair_type == "معدة" %}
    محضر تسليم وتجربة معدة
  {% elif doc.repair_type == "مجموعة" %}
    محضر تسليم وتجربة مجموعة
  {% else %}
    محضر تسليم وتجربة
  {% endif %}
</div>


  <!-- Gray separator line -->
  <div class="header-line"></div>
</div>
