l": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "مخصصةHTML", "fieldtype": "HTML", "options": "<!-- Footer for Frappe Print Format -->
<style>
  .footer-wrap {
    width: 100%;
    display: table;
    table-layout: fixed;
    direction: rtl;
    margin-top: 40px;
    font-family: "Cairo", "Amiri", "Tahoma", "Arial", sans-serif;
  }

  .footer-col {
    display: table-cell;
    width: 33%;
    vertical-align: top;
    text-align: center;
    padding: 5px 10px;
    border-left: 1px solid #ccc;
  }

  .footer-col:last-child {
    border-left: none;
  }

  .footer-role {
    font-size: 15px;
    font-weight: 700;
    text-decoration: underline;
    margin-bottom: 6px;
  }

  .footer-field {
    font-size: 14px;
    font-weight: 500;
    margin-bottom: 6px;
  }

  .footer-sign {
    height: 50px;
    border-top: 1px dashed #999;
    width: 70%;
    margin: 15px auto 0 auto;
  }

  .footer-note {
    text-align: center;
    font-size: 15px;
    font-weight: 600;
    margin-top: 25px;
    color: #222;
  }

  @media print {
    .footer-wrap { margin-top: 30px; }
    .footer-role { font-size: 14px; }
    .footer-field { font-size: 13px; }
    .footer-sign { height: 45px; }
    .footer-note { font-size: 14px; }
  }
</style>

<!-- الجملة الختامية -->
<div class="footer-note">
  تم تجربة المعدة / المجموعة أمام المندوب ووجدت خالية من الأعطال
</div>

<div class="footer-wrap">
  <!-- العمود الأول: المفتش -->
  <div class="footer-col">
    <div class="footer-role">المُستلِم</div>
    <div class="footer-field">الدرجة: ___________________</div>
    <div class="footer-field">الاسم: ___________________</div>
    <div class="footer-field">التوقيع:</div>
    <div class="footer-sign"></div>
  </div>

  <!-- العمود الثاني: ضابط الورشة -->
  <div class="footer-col">
    <div class="footer-role">ضابط الورشة</div>
    <div class="footer-field">الدرجة: ___________________</div>
    <div class="footer-field">الاسم: ___________________</div>
    <div class="footer-field">التوقيع:</div>
    <div class="footer-sign"></div>
  </div>

  <!-- العمود الثالث: قائد الوحدة -->
  <div class="footer-col">
    <div class="footer-role">قائد الوحدة</div>
    <div class="footer-field">الدرجة: ___________________</div>
    <div class="footer-field">الاسم: ___________________</div>
    <div class="footer-field">التوقيع:</div>
    <div class="footer-sign"></div>
  </div>
</div>
